package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.context.annotation.Bean;import org.junit.jupiter.api.*;
import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseP3MediaTest extends PhaseP3Fixtures {
 @TestConfiguration static class Media {@Bean SyntheticMedia syntheticMedia(){return new SyntheticMedia();}}
 static class SyntheticMedia implements ClinicalMediaProvider {boolean recording,approved=true;public boolean authorized(String country,String mode){return approved&&country.equals("IR");}public Admission admit(UUID e,UUID p,UUID s,UUID a,String mode,Instant expiry){return new Admission("https://synthetic-media.example.test",a.toString(),expiry,recording,false);}public void terminate(UUID e){}public void revoke(UUID e,UUID p,UUID s){}public boolean connected(UUID e,UUID p,UUID s){return false;}}
 @Autowired SyntheticMedia provider;
 @BeforeEach void audio(){provider.recording=false;provider.approved=true;commerce.change(learner.id(),appointment,new ClinicCommerce.Change(1,"CANCEL","Replace with synthetic audio fixture"));UUID slot=db.queryForObject("INSERT INTO professional_availability_slots(id,professional_user_id,starts_at,ends_at,consultation_mode,status,governed) VALUES(uuidv7(),?,CURRENT_TIMESTAMP-INTERVAL '1 minute',CURRENT_TIMESTAMP+INTERVAL '29 minutes','AUDIO','BOOKED',TRUE) RETURNING id",UUID.class,author.id());appointment=db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,availability_slot_id,scheduled_at,ends_at,consultation_mode,status,clinic_governed,booking_key,price_units,commission_units,provider_fee_units,currency,policy_id,terms_snapshot,profession_snapshot,confirmed_at) SELECT ?,?,id,starts_at,ends_at,'AUDIO','CONFIRMED',TRUE,?,0,0,0,'IRR',?,'Synthetic audio exact accepted terms','PSYCHOLOGIST',CURRENT_TIMESTAMP FROM professional_availability_slots WHERE id=? RETURNING id",UUID.class,learner.id(),author.id(),UUID.randomUUID(),policy,slot);for(String kind:List.of("PLATFORM_TERMS","CARE_CONSENT","DATA_NOTICE","MEDIA_DISCLOSURE")){UUID draft=care.draftNotice(issuer.id(),new ClinicalCare.Notice(kind,"qa-media-"+UUID.randomUUID(),"en","AUDIO","Synthetic original media disclosure and clinical scope, not a real operational approval.",Instant.now().minusSeconds(60),Instant.now().plusSeconds(3600)));care.approveNotice(reviewer.id(),draft,1);}}
 @Test void singleUseAdmissionIsBoundToParticipantAndAuthenticationSession(){UUID id=active(),grant=care.admission(learner.id(),learner.session(),id);assertThatThrownBy(()->care.exchange(other.id(),other.session(),id,grant)).isInstanceOf(NotFoundException.class);var admission=care.exchange(learner.id(),learner.session(),id,grant);assertThat(admission.recording()).isFalse();assertThatThrownBy(()->care.exchange(learner.id(),learner.session(),id,grant)).isInstanceOf(ForbiddenException.class);}
 @Test void unapprovedProviderAndRecordingAreRefused(){UUID id=active();provider.approved=false;assertThatThrownBy(()->care.admission(learner.id(),learner.session(),id)).isInstanceOf(ForbiddenException.class);provider.approved=true;UUID grant=care.admission(learner.id(),learner.session(),id);provider.recording=true;assertThatThrownBy(()->care.exchange(learner.id(),learner.session(),id,grant)).isInstanceOf(ForbiddenException.class);}
 @Test void reconnectTimeoutIsTechnicalFailureNotProfessionalNoShow(){UUID id=active();care.mediaFailure(learner.id(),learner.session(),id,"RECONNECT_TIMEOUT");assertThat(care.status(learner.id(),learner.session(),id).get("state")).isEqualTo("TECHNICAL_FAILURE");assertThat(db.queryForObject("SELECT status FROM consultation_requests WHERE id=?",String.class,appointment)).isEqualTo("TECHNICAL_FAILURE");}
}
